import json, asyncio
from playwright.async_api import async_playwright
exec(open('/home/claude/ctest.py').read().split("async def run(")[0])
C=json.load(open('/home/claude/capture_export.json'))
G={"game_capture_raw":C['runs'],"game_loads":C['loads'],"game_events":C['events'],"game_balance":C['balance'],"game_ops_recent":C['ops'],"game_flight_pnl":C['pnl']}
async def go():
    async with async_playwright() as p:
        b=await p.chromium.launch(); ctx=await b.new_context(viewport={"width":1440,"height":1000})
        await ctx.add_init_script("localStorage.setItem('gander-auth', JSON.stringify({access_token:'t'}));")
        pg=await ctx.new_page(); errs=[]; pg.on("pageerror", lambda e: errs.append(str(e)[:220])); ST=stub(G)
        async def route(r):
            u=r.request.url
            if "supabase" in u and u.endswith(".js"): await r.fulfill(body=ST, content_type="application/javascript")
            elif "/rest/v1/planner_data" in u: await r.fulfill(body=json.dumps([{"value":json.loads(DATA)}]), content_type="application/json")
            else: await r.continue_()
        await pg.route("**/*", route); await pg.goto("http://127.0.0.1:8765/planner/"); await pg.wait_for_timeout(3500)
        tabs=await pg.evaluate("[...document.querySelectorAll('nav button')].map(b=>b.textContent)"); print("tabs:", tabs)
        # Review (finance view)
        await pg.evaluate("document.querySelector('nav button[data-view=finance]').click()"); await pg.wait_for_timeout(1200)
        print("Review title:", await pg.evaluate("document.querySelector('.vh h1').textContent"))
        print("group KPIs:", await pg.evaluate("[...document.querySelectorAll('.gk')].map(x=>x.textContent.replace(/\\s+/g,' ').trim())"))
        await pg.screenshot(path="/home/claude/shots/rv_top.png", clip={"x":0,"y":0,"width":1440,"height":760})
        await pg.evaluate("document.querySelector('[data-final=Kingfisher]').click()"); await pg.wait_for_timeout(1200)
        chips=await pg.evaluate("[...document.querySelectorAll('.rpf .mf')].map(x=>x.textContent.trim())"); print("filters:", chips)
        await pg.evaluate("(()=>{const h=[...document.querySelectorAll('h3')].find(x=>/^Route profit/.test(x.textContent)); h.scrollIntoView({block:'start'}); window.scrollBy(0,-90)})()"); await pg.wait_for_timeout(500)
        await pg.screenshot(path="/home/claude/shots/rv_rp.png", clip={"x":0,"y":0,"width":1440,"height":900})
        n0=await pg.evaluate("document.querySelectorAll('#rp-table tr[data-rprow]').length")
        await pg.evaluate("document.querySelector('[data-rpsig=raise]') && document.querySelector('[data-rpsig=raise]').click()"); await pg.wait_for_timeout(600)
        n1=await pg.evaluate("document.querySelectorAll('#rp-table tr[data-rprow]').length")
        await pg.evaluate("document.querySelector('[data-rpsig=\"\"]').click()"); await pg.wait_for_timeout(500)
        await pg.fill("#rp-q", "lhr"); await pg.wait_for_timeout(300)
        n2=await pg.evaluate("[...document.querySelectorAll('#rp-table tr[data-rprow]')].filter(r=>r.style.display!=='none').length")
        await pg.evaluate("document.querySelector('[data-rpdays=\"1\"]').click()"); await pg.wait_for_timeout(500)
        note=await pg.evaluate("(document.querySelector('.rpf + .note')||{textContent:''}).textContent.slice(0,70)")
        print(f"route rows: all {n0} | 'raise fares' filter {n1} | search 'lhr' {n2} | last-day period note: {note}")
        man=await pg.evaluate("(()=>{const h=[...document.querySelectorAll('h3')].find(x=>/^Manual entry/.test(x.textContent)); return h? [...h.closest('.board').querySelectorAll('summary')].map(s=>s.textContent.trim()):'none'})()"); print("manual entry sections:", man)
        # Check (review view)
        await pg.evaluate("document.querySelector('nav button[data-view=review]').click()"); await pg.wait_for_timeout(1200)
        print("Check title:", await pg.evaluate("document.querySelector('.vh h1').textContent"))
        print("daily report:", await pg.evaluate("(()=>{const h=[...document.querySelectorAll('h3')].find(x=>/^Daily load report/.test(x.textContent)); return h.closest('.board').querySelector('.count').textContent.replace(/\\s+/g,' ')})()"))
        print("hand-entry gone from Check:", await pg.evaluate("!document.querySelector('#view [data-q]')"))
        sec=await pg.evaluate("[...document.querySelectorAll('h4.gh')].map(x=>x.childNodes[0].textContent.trim()+' '+((x.querySelector('.note')||{textContent:''}).textContent.match(/· (\\d+)$/)||['',''])[1])")
        print("growth sections:", [x for x in sec if x][:10])
        await pg.evaluate("(()=>{const h=[...document.querySelectorAll('h4.gh')].find(x=>/Ready for another flight/.test(x.textContent)); h.scrollIntoView({block:'start'}); window.scrollBy(0,-90)})()"); await pg.wait_for_timeout(400)
        await pg.screenshot(path="/home/claude/shots/ck_growth.png", clip={"x":0,"y":0,"width":1440,"height":800})
        # Home
        await pg.evaluate("document.querySelector('nav button[data-view=home]').click()"); await pg.wait_for_timeout(1200)
        att=await pg.evaluate("[...document.querySelectorAll('ul.att:not(.sub) > li')].map(li=>li.querySelector('summary')? li.querySelector('summary').textContent.replace(/\\s+/g,' ').trim()+' [group]' : li.textContent.replace('×','').trim().slice(0,90))")
        print("needs attention:", att)
        print("coming up filters:", await pg.evaluate("[...document.querySelectorAll('.upf .mf')].map(x=>x.textContent)"))
        print("errors:", errs); await b.close()
asyncio.run(go())
